// Builds the customer support report shown and exported by the support tab.
export function buildReport(events) {
  const expansions = events.filter((e) => e.kind === 'expansion').length;
  const scores = events.filter((e) => e.kind === 'score').map((e) => e.value);
  const avg = scores.length ? scores.reduce((a, b) => a + b, 0) / scores.length : null;
  return { expansions, avgScore: avg };
}

export function averageScore(events) {
  const scores = events.filter((e) => e.kind === 'score').map((e) => e.value);
  return scores.length ? scores.reduce((a, b) => a + b, 0) / scores.length : null;
}

export function exportReport(events, format) {
  const report = buildReport(events);
  if (format === 'json') return JSON.stringify(report);
  return `expansions,avgScore\n${report.expansions},${report.avgScore ?? ''}`;
}

overlay.src/support-tab.mjs:
import { buildReport, averageScore, exportReport } from './report.mjs';

// Renders the Customer Support statistics tab as an HTML string.
export function renderSupportTab(events) {
  const report = buildReport(events);
  return [
    '<section id="support-tab">',
    `<div class="card" id="expansions-card">Expansions: ${report.expansions}</div>`,
    `<div class="card" id="avg-score-card">Average score: ${report.avgScore ?? '-'}</div>`,
    `<div class="card" id="csat-mean-card">CSAT mean: ${averageScore(events) ?? '-'}</div>`,
    '<button id="download-csv" data-format="csv">Download CSV</button>',
    '<button id="download-json" data-format="json">Download JSON</button>',
    '<button id="copy-survey-link">Copy survey link</button>',
    '<div class="panel" id="manual-score-panel">Manual satisfaction score <input type="number" min="1" max="5"> <button>Save</button></div>',
    '</section>',
  ].join('\n');
}

export function onDownload(events, format) {
  return exportReport(events, format);
}

