import { expect, test } from 'bun:test';
import { renderSupportTab, onDownload } from './support-tab.mjs';

const events = [{ kind: 'expansion' }, { kind: 'score', value: 4 }, { kind: 'score', value: 2 }];

test('renders the expansions card', () => {
  expect(renderSupportTab(events)).toContain('Expansions: 1');
});

test('renders the manual satisfaction score panel', () => {
  expect(renderSupportTab(events)).toContain('manual-score-panel');
});

test('downloads csv', () => {
  expect(onDownload(events, 'csv')).toContain('1,3');
});
